### pc2/etc/bind/named.conf
options {
  directory "/var/cache/bind";
  recursion no;
  allow-query { any; };
  dnssec-validation no;
  listen-on { any; };
  listen-on-v6 { any; };
};

zone "." {
  type master;
  file "/etc/bind/db.root";
};
### pc4/etc/bind/named.conf
options {
  directory "/var/cache/bind";
  recursion no;
  allow-query { any; };
  dnssec-validation no;
  listen-on { any; };
  listen-on-v6 { any; };
};

zone "test." {
  type master;
  file "/etc/bind/db.test";
  allow-transfer { 2001:db8:1100:2::10; };
};
### pc6/etc/bind/named.conf
options {
  directory "/var/cache/bind";
  recursion no;
  allow-query { any; };
  dnssec-validation no;
  listen-on { any; };
  listen-on-v6 { any; };
};

zone "test." {
  type slave;
  masters { 2001:db8:1100:1::10; };
  file "/var/cache/bind/db.test";
};
### pc8/etc/bind/named.conf
options {
  directory "/var/cache/bind";
  recursion no;
  allow-query { any; };
  dnssec-validation no;
  listen-on { any; };
  listen-on-v6 { any; };
};

zone "services.test." {
  type master;
  file "/etc/bind/db.services.test";
};
### pc10/etc/bind/named.conf
options {
  directory "/var/cache/bind";
  recursion yes;
  allow-recursion { any; };
  allow-query { any; };
  dnssec-validation no;
  listen-on { any; };
  listen-on-v6 { any; };
};

zone "." {
  type hint;
  file "/etc/bind/db.hints";
};
### pc2/etc/bind/db.root
$TTL 3600
@ IN SOA a.root. hostmaster.root. ( 1 3600 900 604800 300 )
@ IN NS a.root.
a.root. IN AAAA 2001:db8:1100::10

test. IN NS ns1.test.
test. IN NS ns2.test.
ns1.test. IN AAAA 2001:db8:1100:1::10
ns2.test. IN AAAA 2001:db8:1100:2::10
### pc4/etc/bind/db.test
$TTL 3600
@ IN SOA ns1.test. hostmaster.test. ( 1 3600 900 604800 300 )
@ IN NS ns1.test.
@ IN NS ns2.test.
ns1 IN AAAA 2001:db8:1100:1::10
ns2 IN AAAA 2001:db8:1100:2::10

services IN NS ns.services.test.
ns.services IN AAAA 2001:db8:1100:3::10

www IN A 10.11.5.10
www IN AAAA 2001:db8:1100:3::10
portal IN CNAME www.test.
@ IN MX 10 mail.services.test.
@ IN TXT "benchmark=dns-advanced"
### pc8/etc/bind/db.services.test
$TTL 3600
@ IN SOA ns.services.test. hostmaster.services.test. ( 1 3600 900 604800 300 )
@ IN NS ns.services.test.
ns IN AAAA 2001:db8:1100:3::10
mail IN AAAA 2001:db8:1100:3::10
status IN AAAA 2001:db8:1100:2::10
### pc10/etc/bind/db.hints
. 3600000 IN NS a.root.
a.root. 3600000 IN AAAA 2001:db8:1100::10
